# Stock-image scan: settings getter/setter sites and orientation strings.
# Read-only. Do not edit this file after it has run.
import hashlib
from pathlib import Path

BASE = 0x60021020
GETTER = 0x60063380
SETTER = 0x60063431
KEYS = {
    0xE91: 'e91', 0x1DB1: '1db1', 0x1DC1: '1dc1', 0x99A1: '99a1', 0x5962: '5962',
    0x88B2: '88b2', 0x9A41: '9a41', 0x1DD1: '1dd1', 0xDFA1: 'dfa1', 0x99D2: '99d2',
    0x84D1: '84d1', 0x9FA1: '9fa1', 0x90D1: '90d1', 0x1DE1: '1de1', 0x1DF1: '1df1',
    0x5A11: '5a11', 0x90A1: '90a1', 0x1E01: '1e01',
}
STRINGS = [
    b'PER_ROTATE', b'ACC_MAIN', b'ACC_SENS', b'ROTATE_', b'Orientation',
    b'orientation', b'ORIENT', b'acc-adj', b'WHO_AM_I', b'PER_SLOPE',
    b'ACC_PROBE', b'rotate', b'LEVEL', b'MODE_AF_ORIENT', b'MODE_AF_AREA',
    b'MODE_AF_FRAME', b'MODE_AF_HOME',
]

img_path = Path('inputs/00_0100_50000020.decoded.bin')
res_path = Path('inputs/02_0106_458c0020.decoded.bin')
img = img_path.read_bytes()
res = res_path.read_bytes()
n = len(img)


def sha(data):
    return hashlib.sha256(data).hexdigest()


def s32(o):
    v = int.from_bytes(img[o:o + 4], 'little')
    return v - 0x100000000 if v & 0x80000000 else v


def s16_at(buf, o):
    v = int.from_bytes(buf[o:o + 2], 'little')
    return v - 0x10000 if v & 0x8000 else v


def u32(o):
    return int.from_bytes(img[o:o + 4], 'little')


def parse_movs(end, window=48):
    start = max(0, end - window)
    movs = []
    i = start
    while i + 3 <= end:
        op = img[i]
        pc = BASE + i
        if op == 0xFC and i + 6 <= end and 0xCC <= img[i + 1] <= 0xCF:
            reg = img[i + 1] - 0xCC
            imm = u32(i + 2)
            movs.append((pc, f'd{reg}', imm, 'imm32'))
            i += 6
            continue
        if op == 0xFC and i + 6 <= end and 0xDC <= img[i + 1] <= 0xDF:
            reg = img[i + 1] - 0xDC
            imm = u32(i + 2)
            movs.append((pc, f'a{reg}', imm, 'imm32'))
            i += 6
            continue
        if 0x2C <= op <= 0x2F and i + 3 <= end:
            reg = op - 0x2C
            imm = int.from_bytes(img[i + 1:i + 3], 'little')
            movs.append((pc, f'd{reg}', imm, 'imm16'))
            i += 3
            continue
        i += 1
    return movs


sites = []
i = 0
while i < n - 6:
    op = img[i]
    pc = BASE + i
    target = None
    kind = None
    length = 0
    if op == 0xDD and i + 7 <= n:
        target = (pc + s32(i + 1)) & 0xFFFFFFFF
        kind, length = 'call32', 7
    elif op == 0xCD and i + 5 <= n:
        target = (pc + s16_at(img, i + 1)) & 0xFFFFFFFF
        kind, length = 'call16', 5
    elif op == 0xFC and img[i + 1] == 0xFF and i + 6 <= n:
        target = (pc + s32(i + 2)) & 0xFFFFFFFF
        kind, length = 'calls32', 6
    elif op == 0xFA and img[i + 1] == 0xFF and i + 4 <= n:
        target = (pc + s16_at(img, i + 2)) & 0xFFFFFFFF
        kind, length = 'calls16', 4
    if target in (GETTER, SETTER):
        movs = parse_movs(i)
        d0 = next((m for m in reversed(movs) if m[1] == 'd0'), None)
        d1 = next((m for m in reversed(movs) if m[1] == 'd1'), None)
        sites.append({
            'pc': pc, 'kind': kind, 'len': length,
            'api': 'get' if target == GETTER else 'set',
            'd0': None if d0 is None else d0[2],
            'd0_at': None if d0 is None else d0[0],
            'd0_w': None if d0 is None else d0[3],
            'd1': None if d1 is None else d1[2],
            'd1_at': None if d1 is None else d1[0],
        })
    i += 1

lines = []
lines.append(f'main sha256 {sha(img)} bytes {len(img)}')
lines.append(f'res  sha256 {sha(res)} bytes {len(res)}')
tail = BASE + 0xA6E3EA
lines.append(f'stock byte at 0x60a8f40a file+0xA6E3EA = {img[0xA6E3EA]:02x} (overlay reconcile site)')
lines.append(f'getter sites {sum(1 for s in sites if s["api"]=="get")} setter sites {sum(1 for s in sites if s["api"]=="set")}')

hist = {}
for s in sites:
    k = s['d0']
    hist[k] = hist.get(k, 0) + 1
lines.append('key histogram (d0 immediate before call):')
for k, c in sorted(hist.items(), key=lambda kv: (-kv[1], -1 if kv[0] is None else kv[0])):
    name = 'none' if k is None else KEYS.get(k, '')
    lines.append(f'  {("?" if k is None else hex(k)):10} {c:5} {name}')

lines.append('sites for named keys:')
for s in sites:
    if s['d0'] in KEYS:
        lines.append(
            f"  {s['pc']:08x} {s['api']:3} {s['kind']:8} key {KEYS[s['d0']]} "
            f"d0={s['d0']:#x}@{s['d0_at']:08x}/{s['d0_w']} "
            f"d1={None if s['d1'] is None else hex(s['d1'])}@"
            f"{None if s['d1_at'] is None else format(s['d1_at'], '08x')}"
        )

lines.append('bare mov immediates of e91/1db1/1dc1:')
want = {0xE91, 0x1DB1, 0x1DC1}
i = 0
bare = 0
while i < n - 5:
    op = img[i]
    if op == 0xFC and i + 6 <= n and img[i + 1] in (0xCC, 0xCD, 0xCE, 0xCF, 0xDC, 0xDD, 0xDE, 0xDF):
        imm = u32(i + 2)
        if imm in want:
            lines.append(f'  {BASE + i:08x} op fc{img[i + 1]:02x} imm {imm:#x}')
            bare += 1
        i += 6
        continue
    if 0x2C <= op <= 0x2F and i + 3 <= n:
        imm = int.from_bytes(img[i + 1:i + 3], 'little')
        if imm in want:
            lines.append(f'  {BASE + i:08x} op {op:02x} imm {imm:#x}')
            bare += 1
        i += 3
        continue
    i += 1
lines.append(f'bare count {bare}')


def find_strings(buf, base, label):
    out = []
    for needle in STRINGS:
        start = 0
        hits = 0
        while hits < 12:
            j = buf.find(needle, start)
            if j < 0:
                break
            lo = j
            while lo > 0 and 32 <= buf[lo - 1] < 127:
                lo -= 1
            hi = j
            while hi < len(buf) and 32 <= buf[hi] < 127:
                hi += 1
            text = buf[lo:hi].decode('ascii', 'replace')
            if len(text) > 120:
                text = text[:120] + '...'
            out.append(f'  {label} {base + j:08x} {needle.decode()} | {text}')
            hits += 1
            start = j + 1
        if hits == 0:
            out.append(f'  {label} none {needle.decode()}')
    return out


lines.append('strings in main:')
lines.extend(find_strings(img, BASE, 'main'))
lines.append('strings in resource (file offset, not a runtime address):')
lines.extend(find_strings(res, 0, 'res'))

# UTF-16LE of a few menu words in the resource
lines.append('utf16 resource hits:')
for word in ['Orientation', 'AF Target', 'Linked', 'PER_ROTATE', 'ACC_MAIN']:
    enc = word.encode('utf-16le')
    start = 0
    hits = 0
    while hits < 6:
        j = res.find(enc, start)
        if j < 0:
            break
        lines.append(f'  res+{j:08x} utf16 {word}')
        hits += 1
        start = j + 2
    if hits == 0:
        lines.append(f'  res none utf16 {word}')

# hex window of the E147 accelerometer notes (cached = native - 0x50000000 + BASE)
lines.append('hex at noted ACC addresses:')
for native, name in [
    (0x50049616, 'enable-set'), (0x50049621, 'enable-clr'), (0x50049640, 'ACC_MAIN'),
    (0x50049771, 'probe'),
]:
    addr = BASE + (native - 0x50000000)
    off = addr - BASE
    window = img[off - 16:off + 48]
    lines.append(f'  {name} native {native:#x} cached {addr:#x}')
    lines.append('  ' + window.hex())

text = '\n'.join(lines) + '\n'
Path('work/out/scan-keys-s1.txt').write_text(text, encoding='utf-8')
print(text)
